{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2184-06-06 15:05:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. I’ve been reviewing your case. You were admitted today with worsening abdominal pain, nausea, and vomiting. Can you tell me how you’ve been feeling?"
    },
    {
      "turn_number": 2,
      "time": "2184-06-06 15:06:00",
      "speaker": "Patient",
      "text": "It’s been really bad. The pain is constant, mostly in my upper belly and around the belly button. I can’t keep anything down, not even water."
    },
    {
      "turn_number": 3,
      "time": "2184-06-06 15:07:00",
      "speaker": "Doctor",
      "text": "I see. And your G-tube has been draining a lot?"
    },
    {
      "turn_number": 4,
      "time": "2184-06-06 15:08:00",
      "speaker": "Patient",
      "text": "Yes, it’s been draining dark green fluid with chunks. It’s been like this before, but it’s worse now."
    },
    {
      "turn_number": 5,
      "time": "2184-06-06 15:09:00",
      "speaker": "Doctor",
      "text": "That makes sense. Given your history of sclerosing mesenteritis and many surgeries, this sounds like another partial bowel obstruction from adhesions."
    },
    {
      "turn_number": 6,
      "time": "2184-06-06 15:10:00",
      "speaker": "Patient",
      "text": "So it’s not a new problem? But why is it flaring up again?"
    },
    {
      "turn_number": 7,
      "time": "2184-06-06 15:11:00",
      "speaker": "Doctor",
      "text": "It’s likely due to the scar tissue from your past surgeries. These adhesions can cause the bowel to kink or slow down, leading to symptoms like this."
    },
    {
      "turn_number": 8,
      "time": "2184-06-06 15:12:00",
      "speaker": "Patient",
      "text": "Will I need surgery again?"
    },
    {
      "turn_number": 9,
      "time": "2184-06-06 15:13:00",
      "speaker": "Doctor",
      "text": "Surgery isn’t recommended right now. With so many prior operations, the risk is too high. We’ll manage this conservatively."
    },
    {
      "turn_number": 10,
      "time": "2184-06-06 15:14:00",
      "speaker": "Patient",
      "text": "Okay, that’s a relief. What does conservative mean?"
    },
    {
      "turn_number": 11,
      "time": "2184-06-06 15:15:00",
      "speaker": "Doctor",
      "text": "We’ll keep your stomach decompressed with the G-tube, give you IV fluids, and provide nutrition through TPN since you can’t eat."
    },
    {
      "turn_number": 12,
      "time": "2184-06-06 15:16:00",
      "speaker": "Patient",
      "text": "I’ve had TPN before. It helps, but I hate the line infections."
    },
    {
      "turn_number": 13,
      "time": "2184-06-06 15:17:00",
      "speaker": "Doctor",
      "text": "I understand. We’re monitoring your femoral line closely. It looks clean, and we’re being careful with sterile technique."
    },
    {
      "turn_number": 14,
      "time": "2184-06-06 15:18:00",
      "speaker": "Patient",
      "text": "Thanks. The pain is still really bad. Is there anything stronger we can do?"
    },
    {
      "turn_number": 15,
      "time": "2184-06-06 15:19:00",
      "speaker": "Doctor",
      "text": "We’ve started rectal Dilaudid, which seems to be helping. We’ll keep adjusting until your pain is better controlled."
    },
    {
      "turn_number": 16,
      "time": "2184-06-06 15:20:00",
      "speaker": "Patient",
      "text": "I’ve used that before. It helps, but I worry about side effects."
    },
    {
      "turn_number": 17,
      "time": "2184-06-06 15:21:00",
      "speaker": "Doctor",
      "text": "We’ll watch for constipation or drowsiness. But for now, pain control is a priority."
    },
    {
      "turn_number": 18,
      "time": "2184-06-07 08:30:00",
      "speaker": "Doctor",
      "text": "Good morning. Your labs are stable. We’ve started your TPN today to support your nutrition."
    },
    {
      "turn_number": 19,
      "time": "2184-06-07 08:31:00",
      "speaker": "Patient",
      "text": "Is the TPN going to stay the same when I go home?"
    },
    {
      "turn_number": 20,
      "time": "2184-06-07 08:32:00",
      "speaker": "Doctor",
      "text": "Yes, you’ll continue daily TPN at home. We’re using a non-standard formula tailored to your needs."
    },
    {
      "turn_number": 21,
      "time": "2184-06-07 08:33:00",
      "speaker": "Patient",
      "text": "Okay. And my heart is still racing. It’s been in the 120s."
    },
    {
      "turn_number": 22,
      "time": "2184-06-07 08:34:00",
      "speaker": "Doctor",
      "text": "We noticed that. It’s likely due to dehydration and pain. Your fluids are being increased, and we’ll monitor it."
    },
    {
      "turn_number": 23,
      "time": "2184-06-07 08:35:00",
      "speaker": "Patient",
      "text": "I hope it settles. It makes me dizzy sometimes."
    },
    {
      "turn_number": 24,
      "time": "2184-06-07 08:36:00",
      "speaker": "Doctor",
      "text": "We’ll keep an eye on your blood pressure and symptoms. You’re not lightheaded or orthostatic, which is good."
    },
    {
      "turn_number": 25,
      "time": "2184-06-08 10:00:00",
      "speaker": "Doctor",
      "text": "We’re going to do an upper endoscopy today to look at the blockage in your small bowel."
    },
    {
      "turn_number": 26,
      "time": "2184-06-08 10:01:00",
      "speaker": "Patient",
      "text": "Will they be able to fix it during the procedure?"
    },
    {
      "turn_number": 27,
      "time": "2184-06-08 10:02:00",
      "speaker": "Doctor",
      "text": "It’s unlikely. The scope may not even get past the tight area due to adhesions. But it will help us confirm what’s going on."
    },
    {
      "turn_number": 28,
      "time": "2184-06-08 10:03:00",
      "speaker": "Patient",
      "text": "I’ve had that before. It’s uncomfortable, but I’ll do it if it helps."
    },
    {
      "turn_number": 29,
      "time": "2184-06-08 13:15:00",
      "speaker": "Doctor",
      "text": "The endoscopy is done. The scope couldn’t pass a sharp bend early in the small bowel. It’s likely an adhesion or anastomotic site."
    },
    {
      "turn_number": 30,
      "time": "2184-06-08 13:16:00",
      "speaker": "Patient",
      "text": "So nothing changed. It’s still blocked?"
    },
    {
      "turn_number": 31,
      "time": "2184-06-08 13:17:00",
      "speaker": "Doctor",
      "text": "It’s a chronic partial blockage. The bowel beyond is normal, but motility is poor. We’ll continue with current management."
    },
    {
      "turn_number": 32,
      "time": "2184-06-09 09:00:00",
      "speaker": "Doctor",
      "text": "We did a small bowel follow-through with contrast. It showed the blockage is stable. The contrast passed into the distal jejunum."
    },
    {
      "turn_number": 33,
      "time": "2184-06-09 09:01:00",
      "speaker": "Patient",
      "text": "So it’s not getting worse?"
    },
    {
      "turn_number": 34,
      "time": "2184-06-09 09:02:00",
      "speaker": "Doctor",
      "text": "No, it’s the same as before. That’s actually good news. It means we’re not dealing with a new twist or complete blockage."
    },
    {
      "turn_number": 35,
      "time": "2184-06-09 09:03:00",
      "speaker": "Patient",
      "text": "And the pain? It’s better with the Dilaudid, but I don’t want to rely on it forever."
    },
    {
      "turn_number": 36,
      "time": "2184-06-09 09:04:00",
      "speaker": "Doctor",
      "text": "We’ve arranged for a compounded version of the rectal Dilaudid so you can continue it at home safely."
    },
    {
      "turn_number": 37,
      "time": "2184-06-09 09:05:00",
      "speaker": "Patient",
      "text": "That’s a relief. I was worried about access."
    },
    {
      "turn_number": 38,
      "time": "2184-06-10 08:45:00",
      "speaker": "Doctor",
      "text": "Your labs are improving. Your kidney function is good, and your hemoglobin is stable despite being low."
    },
    {
      "turn_number": 39,
      "time": "2184-06-10 08:46:00",
      "speaker": "Patient",
      "text": "I’m always a bit anemic. Is that from the bowel issues?"
    },
    {
      "turn_number": 40,
      "time": "2184-06-10 08:47:00",
      "speaker": "Doctor",
      "text": "Partly. Chronic inflammation and poor absorption play a role. We’ll keep monitoring and supplementing iron."
    },
    {
      "turn_number": 41,
      "time": "2184-06-10 08:48:00",
      "speaker": "Patient",
      "text": "And my thyroid? I take levothyroxine daily."
    },
    {
      "turn_number": 42,
      "time": "2184-06-10 08:49:00",
      "speaker": "Doctor",
      "text": "Your thyroid levels are stable. Keep taking the same dose. No changes needed."
    },
    {
      "turn_number": 43,
      "time": "2184-06-11 14:00:00",
      "speaker": "Doctor",
      "text": "We’re planning for discharge tomorrow. Your pain is controlled, and you’re stable on TPN and fluids."
    },
    {
      "turn_number": 44,
      "time": "2184-06-11 14:01:00",
      "speaker": "Patient",
      "text": "That’s great. What changes will I have at home?"
    },
    {
      "turn_number": 45,
      "time": "2184-06-11 14:02:00",
      "speaker": "Doctor",
      "text": "You’ll get 3 liters of IV fluids daily—more than before—to prevent dehydration. And you’ll continue the rectal Dilaudid as needed."
    },
    {
      "turn_number": 46,
      "time": "2184-06-11 14:03:00",
      "speaker": "Patient",
      "text": "And the TPN?"
    },
    {
      "turn_number": 47,
      "time": "2184-06-11 14:04:00",
      "speaker": "Doctor",
      "text": "Same as in the hospital. We’ll coordinate with your home care team."
    },
    {
      "turn_number": 48,
      "time": "2184-06-11 14:05:00",
      "speaker": "Patient",
      "text": "I’ll need help at home, right?"
    },
    {
      "turn_number": 49,
      "time": "2184-06-11 14:06:00",
      "speaker": "Doctor",
      "text": "Yes, home health will assist with your lines and monitoring. You’re cleared to go home with services."
    },
    {
      "turn_number": 50,
      "time": "2184-06-12 10:00:00",
      "speaker": "Doctor",
      "text": "You’re doing really well. We’ll discharge you in a few hours. Follow up with your GI and primary doctors soon."
    },
    {
      "turn_number": 51,
      "time": "2184-06-12 10:01:00",
      "speaker": "Patient",
      "text": "Thank you. I feel much better than when I came in."
    },
    {
      "turn_number": 52,
      "time": "2184-06-12 10:02:00",
      "speaker": "Doctor",
      "text": "I’m glad. Keep using the Dilaudid as needed, stay on your fluids, and call if symptoms worsen."
    },
    {
      "turn_number": 53,
      "time": "2184-06-12 10:03:00",
      "speaker": "Patient",
      "text": "I will. And thank you for not pushing surgery. I trust this plan."
    },
    {
      "turn_number": 54,
      "time": "2184-06-12 10:04:00",
      "speaker": "Doctor",
      "text": "We’re here to support you with the safest approach. Take care, and we’ll see you in clinic soon."
    },
    {
      "turn_number": 55,
      "time": "2184-06-12 10:05:00",
      "speaker": "Patient",
      "text": "I appreciate that. Have a good day."
    }
  ],
  "summary": {
    "admission_start": "2184-06-06 14:59:00",
    "admission_end": "2184-06-12 15:00:00",
    "summary_paragraph": "A woman with a long history of sclerosing mesenteritis and 23 prior abdominal surgeries was admitted for worsening abdominal pain, nausea, vomiting, and high G-tube output, consistent with a chronic partial small bowel obstruction due to adhesions. She was managed conservatively with G-tube decompression, TPN, IV fluids, and rectal Dilaudid for pain control. An upper endoscopy confirmed a tight proximal obstruction that could not be traversed, and a small bowel follow-through showed stable findings without complete obstruction. Her tachycardia improved with hydration. Pain control was optimized with a compounded rectal Dilaudid formulation for outpatient use, and her IV fluid regimen was increased to 3 liters daily to prevent future admissions. She was discharged home with services in stable condition, with plans for ongoing TPN, fluid support, and close outpatient follow-up.",
    "problems": [
      "Intestinal or peritoneal adhesions with obstruction (postoperative) (postinfection)",
      "Sclerosing mesenteritis",
      "Dehydration",
      "Gastrostomy status",
      "Other chronic pain",
      "Tachycardia, unspecified",
      "Unspecified acquired hypothyroidism",
      "Anemia, unspecified",
      "Irritable bowel syndrome",
      "Dyspepsia and other specified disorders of function of stomach"
    ]
  }
}
